ee:message.ee:set-payload:
%dw 2.0
output application/java
var orders = {"1001": "IN_TRANSIT", "1002": "PENDING", "1003": "DELIVERED"}
var orderNumber = attributes.uriParams.orderNumber
---
if (attributes.method != "GET")
  { code: 405, body: { message: "Method not allowed" } }
else if (!(orderNumber matches /[0-9]{1,20}/))
  { code: 400, body: { message: "Invalid order number: $(orderNumber)" } }
else if (orders[orderNumber] == null)
  { code: 404, body: { message: "Order $(orderNumber) not found" } }
else
  { code: 200, body: { orderNumber: orderNumber, status: orders[orderNumber] } }
